/* From Uiverse.io by catraco - Tags: simple, small, switcher */
/* Switch - Container */
.__UIV_SCOPE__ .switch {
  --primary: #50F080;
  --secondary: #F05050;
  --dark: #505050;
  --light: #D0D0D0;
  background-color: var(--dark);
  position: relative;
  display: inline-block;
  border-radius: 1rem;
  cursor: pointer;
  width: 50px;
  height: 25px;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .checkbox {
  opacity: 0
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  left: 0;
  top: 50%;
  width: 50%;
  height: 100%;
  transition: .4s;
  border-radius: 100%;
  transform: translateY(-50%);
  border: 4px solid var(--dark);
  background-color: var(--secondary);
}

.__UIV_SCOPE__ .checkbox:checked + .slider {
  background-color: var(--primary);
  transform: translate(100%, -50%);
}
